CREATE EXTENSION IF NOT EXISTS pgcrypto;
CREATE TABLE users(id uuid PRIMARY KEY DEFAULT gen_random_uuid(),email text UNIQUE NOT NULL,password_hash text NOT NULL,email_verified boolean NOT NULL DEFAULT false,created_at timestamptz NOT NULL DEFAULT now());
CREATE TABLE sessions(id uuid PRIMARY KEY DEFAULT gen_random_uuid(),user_id uuid NOT NULL REFERENCES users(id),family_id uuid NOT NULL,token_hash text UNIQUE NOT NULL,expires_at timestamptz NOT NULL,revoked_at timestamptz,created_at timestamptz NOT NULL DEFAULT now());
CREATE INDEX sessions_user ON sessions(user_id);
CREATE TABLE auth_tokens(id uuid PRIMARY KEY DEFAULT gen_random_uuid(),user_id uuid NOT NULL REFERENCES users(id),kind text NOT NULL CHECK(kind IN ('verify','reset')),token_hash text UNIQUE NOT NULL,expires_at timestamptz NOT NULL);
CREATE TABLE workspaces(id uuid PRIMARY KEY DEFAULT gen_random_uuid(),name text NOT NULL,storage_limit bigint NOT NULL DEFAULT 107374182400,video_limit integer NOT NULL DEFAULT 1000,created_at timestamptz NOT NULL DEFAULT now());
CREATE TABLE workspace_members(workspace_id uuid REFERENCES workspaces(id),user_id uuid REFERENCES users(id),role text NOT NULL CHECK(role IN ('owner','admin','editor','viewer')),PRIMARY KEY(workspace_id,user_id));
CREATE TABLE workspace_invites(id uuid PRIMARY KEY DEFAULT gen_random_uuid(),workspace_id uuid NOT NULL REFERENCES workspaces(id),email text NOT NULL,role text NOT NULL CHECK(role IN ('admin','editor','viewer')),token_hash text UNIQUE NOT NULL,expires_at timestamptz NOT NULL);
CREATE TABLE videos(id uuid PRIMARY KEY DEFAULT gen_random_uuid(),workspace_id uuid NOT NULL REFERENCES workspaces(id),title text NOT NULL,description text NOT NULL DEFAULT '',tags text[] NOT NULL DEFAULT '{}',filename text,privacy text NOT NULL DEFAULT 'private' CHECK(privacy IN ('private','unlisted','public')),status text NOT NULL DEFAULT 'draft' CHECK(status IN ('draft','uploading','uploaded','probing','queued','processing','packaging','ready','failed','deleted')),progress jsonb NOT NULL DEFAULT '{}',metadata jsonb,renditions jsonb NOT NULL DEFAULT '[]',source_key text,output_prefix text,error_code text,checksum text,size bigint NOT NULL DEFAULT 0,created_at timestamptz NOT NULL DEFAULT now(),updated_at timestamptz NOT NULL DEFAULT now(),deleted_at timestamptz);
CREATE INDEX videos_workspace_created ON videos(workspace_id,created_at DESC,id DESC);
CREATE INDEX videos_checksum ON videos(workspace_id,checksum);
CREATE INDEX videos_search ON videos USING gin(to_tsvector('simple',title||' '||description));
CREATE TABLE uploads(id uuid PRIMARY KEY DEFAULT gen_random_uuid(),workspace_id uuid NOT NULL REFERENCES workspaces(id),video_id uuid UNIQUE NOT NULL REFERENCES videos(id),filename text NOT NULL,mime_type text NOT NULL,total_size bigint NOT NULL CHECK(total_size>0),uploaded_bytes bigint NOT NULL DEFAULT 0,chunk_size integer NOT NULL DEFAULT 8388608,status text NOT NULL DEFAULT 'uploading' CHECK(status IN ('uploading','finalizing','complete','cancelled','expired','failed')),checksum text NOT NULL,created_at timestamptz NOT NULL DEFAULT now(),expires_at timestamptz NOT NULL);
CREATE TABLE upload_parts(upload_id uuid REFERENCES uploads(id),part_number integer NOT NULL,object_key text NOT NULL,size integer NOT NULL,checksum text NOT NULL,PRIMARY KEY(upload_id,part_number));
CREATE TABLE api_keys(id uuid PRIMARY KEY DEFAULT gen_random_uuid(),workspace_id uuid NOT NULL REFERENCES workspaces(id),name text NOT NULL,key_hash text UNIQUE NOT NULL,scopes text[] NOT NULL,created_at timestamptz NOT NULL DEFAULT now(),last_used_at timestamptz,revoked_at timestamptz);
CREATE TABLE subtitles(id uuid PRIMARY KEY DEFAULT gen_random_uuid(),video_id uuid NOT NULL REFERENCES videos(id),language text NOT NULL,label text NOT NULL,object_key text NOT NULL,is_default boolean NOT NULL DEFAULT false,forced boolean NOT NULL DEFAULT false);
CREATE TABLE video_chapters(id uuid PRIMARY KEY DEFAULT gen_random_uuid(),video_id uuid NOT NULL REFERENCES videos(id),start_seconds double precision NOT NULL CHECK(start_seconds>=0),title text NOT NULL);
CREATE TABLE webhooks(id uuid PRIMARY KEY DEFAULT gen_random_uuid(),workspace_id uuid NOT NULL REFERENCES workspaces(id),url text NOT NULL,secret text NOT NULL,enabled boolean NOT NULL DEFAULT true,created_at timestamptz NOT NULL DEFAULT now());
CREATE TABLE webhook_deliveries(id uuid PRIMARY KEY DEFAULT gen_random_uuid(),webhook_id uuid NOT NULL REFERENCES webhooks(id),event text NOT NULL,payload jsonb NOT NULL,status text NOT NULL DEFAULT 'pending',attempts integer NOT NULL DEFAULT 0,response_status integer,created_at timestamptz NOT NULL DEFAULT now());
CREATE TABLE outbox(id uuid PRIMARY KEY DEFAULT gen_random_uuid(),queue text NOT NULL,payload jsonb NOT NULL,dispatched_at timestamptz,created_at timestamptz NOT NULL DEFAULT now());
CREATE INDEX outbox_pending ON outbox(created_at) WHERE dispatched_at IS NULL;
CREATE TABLE processing_jobs(id uuid PRIMARY KEY DEFAULT gen_random_uuid(),video_id uuid REFERENCES videos(id),queue text NOT NULL,status text NOT NULL,attempt integer NOT NULL DEFAULT 0,error_code text,updated_at timestamptz NOT NULL DEFAULT now());
CREATE TABLE playback_sessions(id uuid PRIMARY KEY DEFAULT gen_random_uuid(),video_id uuid NOT NULL REFERENCES videos(id),expires_at timestamptz NOT NULL,created_at timestamptz NOT NULL DEFAULT now());
CREATE TABLE analytics_events(id uuid PRIMARY KEY,session_id uuid NOT NULL REFERENCES playback_sessions(id),video_id uuid NOT NULL REFERENCES videos(id),event text NOT NULL,position double precision NOT NULL DEFAULT 0,watch_seconds double precision NOT NULL DEFAULT 0,created_at timestamptz NOT NULL DEFAULT now());
CREATE INDEX analytics_video_date ON analytics_events(video_id,created_at);
CREATE TABLE watch_progress(user_id uuid REFERENCES users(id),video_id uuid REFERENCES videos(id),position double precision NOT NULL,updated_at timestamptz NOT NULL DEFAULT now(),PRIMARY KEY(user_id,video_id));
CREATE TABLE notifications(id uuid PRIMARY KEY DEFAULT gen_random_uuid(),workspace_id uuid NOT NULL REFERENCES workspaces(id),video_id uuid REFERENCES videos(id),message text NOT NULL,created_at timestamptz NOT NULL DEFAULT now());
CREATE TABLE audit_logs(id uuid PRIMARY KEY DEFAULT gen_random_uuid(),workspace_id uuid REFERENCES workspaces(id),actor_id text NOT NULL,action text NOT NULL,target_id text,created_at timestamptz NOT NULL DEFAULT now());
CREATE TABLE usage_records(id uuid PRIMARY KEY DEFAULT gen_random_uuid(),workspace_id uuid NOT NULL REFERENCES workspaces(id),video_id uuid REFERENCES videos(id),kind text NOT NULL,amount bigint NOT NULL,idempotency_key text UNIQUE NOT NULL,created_at timestamptz NOT NULL DEFAULT now());
CREATE TABLE playlists(id uuid PRIMARY KEY DEFAULT gen_random_uuid(),workspace_id uuid NOT NULL REFERENCES workspaces(id),name text NOT NULL);
CREATE TABLE playlist_items(playlist_id uuid REFERENCES playlists(id),video_id uuid REFERENCES videos(id),position integer NOT NULL,PRIMARY KEY(playlist_id,video_id));
